-- ============================================================
-- Revisy — MIGRATION_19_pays_programmes.sql
-- Internationalisation multi-pays : public.countries,
--   public.educational_systems, matières de base par pays.
-- Provenance : contexts.js → PAYS_DISPONIBLES (noms bruts, 66 pays).
-- educational_systems : modèles de référence issu de la saisie
--   d utilisateur ; aucune donnée étrangère n est produite sans validation.
-- Matières : référentiel composant (sujets pratiqués), aucune donnée
--   officielle inventée ; les épreuves PDF sont en attente d import.
-- Dépend de MIGRATION_02/_04/_10 (pays sur public.subjects). Idempotent.
-- ============================================================
BEGIN;
CREATE TABLE IF NOT EXISTS public.countries (code text PRIMARY KEY, nom text NOT NULL, devise text NOT NULL, codeDevise text NOT NULL, zone text NOT NULL, langue text NOT NULL DEFAULT 'fr', priorite smallint NOT NULL DEFAULT 3, etat text NOT NULL DEFAULT 'actif', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_countries_zone ON public.countries(zone);
CREATE TABLE IF NOT EXISTS public.educational_systems (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_code text NOT NULL REFERENCES public.countries(code) ON DELETE CASCADE, system_name text NOT NULL, model text NOT NULL, priorite smallint NOT NULL DEFAULT 3, source text NOT NULL DEFAULT 'revizy_referentiel', created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT uq_educational_systems UNIQUE (country_code, system_name));
CREATE INDEX IF NOT EXISTS idx_educational_systems_country ON public.educational_systems(country_code);
COMMIT;
-- Fin MIGRATION_19
